public class Issue89_anagram_word_pair { public static void main(String[] args) { String a="logic", b="cgilo"; boolean same=a.length()==b.length() && a.equalsIgnoreCase(b); for(int i=0;i<a.length()-1 && same;i++) if(a.charAt(i)!=b.charAt(i)) same=false; System.out.println(same?"Anagram":"Not anagram"); } }
